ee:message.ee:set-payload:
%dw 2.0 output application/java var req = if (payload.Request != null) payload.Request else payload --- { serviceCallId: req.Service_Call_ID default req.service_call_id, serviceDescription: req.Service_Description default "", problemDesc: req.ProblemDesc default "", custnmbr: req.CUSTNMBR default "", adrscode: req.ADRSCODE default "", divisions: req.Divisions default "",
// Collect all non-null SummaryNotes into a single string summaryNotes: (req.app_notes default []) filter ($.SummaryNotes != null and $.SummaryNotes != "\u0000" and $.SummaryNotes != "") map $.SummaryNotes joinBy " ",
// Existing material descriptions (lower-cased for dedup) existingDescs: (req.order_materials default []) filter ($.ITEMDESC != null) map lower($.ITEMDESC trim),
// Keep originals for reference appNotes: req.app_notes default [], orderMaterials: req.order_materials default [] }

db:select.db:input-parameters:
#[{
                        serviceCallId: vars.parsedRequest.serviceCallId,
                        embedding:     vars.embedding,
                        topK:          p('recommendation.topKSimilarCalls') as Number default 10
                    }]

ee:message.ee:set-payload:
%dw 2.0
output application/java
var combinedText = lower(
    vars.parsedRequest.serviceDescription ++ " " ++
    vars.parsedRequest.problemDesc        ++ " " ++
    vars.parsedRequest.summaryNotes
)
var stopWords = ["the","was","and","for","with","that","this","from",
                 "been","have","has","had","were","are","not","will",
                 "our","all","they","their","also","more","upon"]
var allWords  = (combinedText scan /\b\w{3,}\b/) map $[0]
var filtered  = allWords filter !(stopWords contains $)
// deduplicate while preserving order
var deduped   = filtered reduce ((word, acc = []) ->
    if (acc contains word) acc else acc + [word])
---
deduped[0..9]   // top 10 keywords

%dw 2.0
output application/java
var rows     = payload
var keywords = vars.keywords
---
rows map (row) -> do {
    var matched = keywords filter (
        (lower(row.itemdesc default "")    contains $) or
        (lower(row.category  default "")    contains $)
    )
    ---
    {
        material_id:      row.material_id,
        itemnmbr:         row.itemnmbr,
        itemdesc:         row.itemdesc,
        category:         row.category,
        catalog_usage:    row.catalog_usage,
        matched_keywords: matched,
        // 0.5 for first match + 0.2 per additional match
        keyword_score:    if (sizeOf(matched) == 0) 0.0
                          else 0.5 + ((sizeOf(matched) - 1) * 0.2)
    }
}

%dw 2.0 output application/java
// ── Weights (mirrors Python constants) ───────────────────────── var FREQ_W = 0.4 var KW_W = 0.3 var POP_W = 0.2
var numSimilar = sizeOf(vars.similarCallIds) var maxUsage = vars.maxUsage as Number var existingIds = vars.existingMaterialIds var existingDesc = vars.parsedRequest.existingDescs // already lower-cased
// ── Helper: should we skip this material? ────────────────────── fun isExcluded(mid, desc) = (existingIds contains mid) or (existingDesc contains lower(desc default "" trim))
// ── Build candidate map from frequency results ───────────────── var freqCandidates = vars.freqResults filter !isExcluded($.material_id, $.itemdesc) map (row) -> { material_id: row.material_id, itemnmbr: row.itemnmbr, itemdesc: row.itemdesc, category: row.category, catalog_usage: row.catalog_usage, freq_score: (row.usage_freq as Number) / (if (numSimilar > 0) numSimilar else 1), pop_score: (row.catalog_usage as Number) / maxUsage, kw_score: 0.0, matched_kw: [], freq_count: row.usage_freq as Number }
// ── Index freq candidates by material_id ────────────────────── var freqById = freqCandidates groupBy $.material_id
// ── Merge keyword results ────────────────────────────────────── var kwEnriched = vars.kwResults filter !isExcluded($.material_id, $.itemdesc) map (kw) -> do { var existing = freqById[kw.material_id] --- if (existing != null) do { var base = existing[0] --- { material_id: base.material_id, itemnmbr: base.itemnmbr, itemdesc: base.itemdesc, category: base.category, catalog_usage: base.catalog_usage, freq_score: base.freq_score, pop_score: base.pop_score, kw_score: kw.keyword_score as Number, matched_kw: kw.matched_keywords, freq_count: base.freq_count, _merged: true } } else { material_id: kw.material_id, itemnmbr: kw.itemnmbr, itemdesc: kw.itemdesc, category: kw.category, catalog_usage: kw.catalog_usage, freq_score: 0.0, pop_score: (kw.catalog_usage as Number) / maxUsage, kw_score: kw.keyword_score as Number, matched_kw: kw.matched_keywords, freq_count: 0, _merged: false } }
// ── IDs already merged (to avoid adding freq-only duplicates) ── var mergedIds = kwEnriched map $.material_id
// ── Freq-only candidates not touched by kw merge ────────────── var freqOnly = freqCandidates filter !(mergedIds contains $.material_id)
// ── Union all candidates ─────────────────────────────────────── var allCandidates = freqOnly ++ kwEnriched
// ── Compute final score ──────────────────────────────────────── var scored = allCandidates map (c) -> { material_id: c.material_id, itemnmbr: c.itemnmbr, itemdesc: c.itemdesc, category: c.category, catalog_usage: c.catalog_usage, score: (FREQ_W * c.freq_score) + (KW_W * c.kw_score) + (POP_W * c.pop_score), reasons: ( (if (c.freq_count > 0) ["Used in $(c.freq_count)/$(numSimilar) similar calls"] else []) ++ (if (!isEmpty(c.matched_kw)) ["Keyword matches: $(c.matched_kw joinBy ', ')"] else []) ) }
// ── Sort descending, take top K ─────────────────────────────── var topK = p('recommendation.topKResults') as Number default 15 var ranked = (scored orderBy -$.score)[0..topK - 1] --- ranked

%dw 2.0
output application/json
var endTimeMs   = now() as Number {unit: 'milliseconds'}
var latencyMs   = endTimeMs - vars.startTimeMs
var req         = vars.parsedRequest
---
{
    Response: {
        Service_Call_ID: req.serviceCallId,
        search_metadata: {
            query_vector_source:      if (!isEmpty(req.serviceDescription)) req.serviceDescription
                                      else if (!isEmpty(req.problemDesc)) req.problemDesc
                                      else "combined_notes",
            total_suggestions_found:  sizeOf(payload),
            search_latency_ms:        latencyMs as Number
        },
        suggested_materials: payload map (rec) -> {
            similarity_score: round(rec.score * 10000) / 10000,
            material_details: {
                material_id: rec.material_id,
                ITEMNMBR:    rec.itemnmbr,
                ITEMDESC:    rec.itemdesc,
                category:    rec.category,
                reasons:     rec.reasons
            }
        }
    }
}

%dw 2.0
output application/json
---
{
    error: {
        code:    400,
        type:    "VALIDATION_ERROR",
        message: error.description default "Invalid request payload"
    }
}

%dw 2.0
output application/json
---
{
    error: {
        code:    500,
        type:    "INTERNAL_ERROR",
        message: "An unexpected error occurred while processing the recommendation request"
    }
}
